  `rating` int(11) DEFAULT NULL,
  `ratingComment` text DEFAULT NULL,
  `adminComment` text DEFAULT NULL,
  `certificated` tinyint(1) NOT NULL DEFAULT 0,
  `checkedIn` tinyint(1) NOT NULL DEFAULT 0,
  `paid` tinyint(1) NOT NULL DEFAULT 0,
  `ratingRequestSentAt` datetime(3) DEFAULT NULL,
  `reminderSentAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Booking_eventId_fkey` (`eventId`),
  KEY `Booking_userId_fkey` (`userId`),
  CONSTRAINT `Booking_eventId_fkey` FOREIGN KEY (`eventId`) REFERENCES `event` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `Booking_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
