DROP TABLE IF EXISTS `newslettercampaign`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `newslettercampaign` (
  `id` varchar(191) NOT NULL,
  `subject` varchar(191) NOT NULL,
  `name` varchar(191) DEFAULT NULL,
  `previewLine` varchar(191) DEFAULT NULL,
  `body` longtext NOT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'DRAFT',
  `design` longtext DEFAULT NULL,
  `sentAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `targetList` varchar(191) NOT NULL DEFAULT 'GENERAL',
  `recipientsCount` int(11) NOT NULL DEFAULT 0,
  `opensCount` int(11) NOT NULL DEFAULT 0,
  `clicksCount` int(11) NOT NULL DEFAULT 0,
  `visible` tinyint(1) NOT NULL DEFAULT 1,
  `fromName` varchar(191) DEFAULT NULL,
  `fromEmail` varchar(191) DEFAULT NULL,
  `replyToName` varchar(191) DEFAULT NULL,
  `replyToEmail` varchar(191) DEFAULT NULL,
  `attachments` text DEFAULT NULL,
  `keywords` text DEFAULT NULL,
  `bcc` varchar(191) DEFAULT NULL,
  `bounceEmail` varchar(191) DEFAULT NULL,
  `trackingEnabled` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

