INSERT INTO `newslettercampaign` VALUES ('66ef43f8-be64-4d6d-babb-624299d93fe8','Schnuppertag / Schnupperkurs / Grundkurs Sonntag 26.8.18','Schnuppertag / Schnupperkurs / Grundkurs Sonntag 26.8.18',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0; height: 38px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center; width: 600px;\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb; width: 520px;\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a></td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 520px; margin: 15px auto;\">\r\n<h3 style=\"text-align: left;\"><span style=\"color: #3491b7;\">Hallo zusammen,</span></h3>\r\n<p style=\"text-align: left;\">morgen treffen wir uns mit<strong> allen die angemeldet sind</strong> um<strong> 8 Uhr&nbsp;</strong>in unserem Fluggelände in<strong> Nonrod.</strong><span style=\"text-align: center;\"></span><strong><br /></strong></p>\r\n<p style=\"text-align: left;\"><strong>Anfahrts-/Geländebeschreibung Nonrod &nbsp;findet ihr hier:</strong></p>\r\n<p style=\"text-align: left;\"><a href=\"https://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/55-nonrod\">https://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/55-nonrod</a><a href=\"https://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/55-nonrod\"></a></p>\r\n<p style=\"text-align: left;\">Bitte seid pünktlich da, damit wir zügig loslegen können :-)!<strong>&nbsp;</strong></p>\r\n<p><img src=\"images/1-Bilderfuernewsletter/schnuppern.JPG\" alt=\"\" width=\"500\" height=\"300\" style=\"float: left;\" />&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: left;\">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;<br />...mehr Infos rund ums\'s Gleitschirmfliegen, zu unseren Kursen und Reisen findet ihr auf unserer Website&nbsp;<a href=\"http://www.fs-hirondelle.de/\">www.fs-hirondelle.de</a>&nbsp;sowie in unserem&nbsp;<a href=\"https://www.youtube.com/channel/UCOwo0Wh2zoX_7nyArBdk_IQ\">YouTube-Kanal</a>&nbsp;- schaut einfach mal rein!</p>\r\n<p style=\"text-align: left;\"><span style=\"color: #3491b7;\"><em><strong>Luftige Grüße</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span><br /></span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim &nbsp;| &nbsp;Am Birnbach 6 - 76829 Landau<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span></span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\">Sparkasse SÜW<br />IBAN: DE32 5485 0010 1700 1976 41&nbsp; <br />BIC: SOLADES1SUW</span></span></p>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\"><br /></span><span style=\"font-weight: bold;\"><a href=\"index.php?option=com_content&amp;view=article&amp;id=42:datenschutzerkl%C3%A4rung&amp;catid=2:allgemein\">Datenschutzerklärung</a></span></span></p>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\"><br /></span><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu ermöglichen</strong></span></p>\r\n</td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #ebebeb; height: 40px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Abmelden{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2018-08-25 05:23:59.000','2018-08-10 05:44:39.000','2026-09-20 10:04:39.404','NEWSLETTER',2124,1739,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('6762601c-4dc2-4bcb-be31-e2b81bb03583','Schnupper-/Grundkurs + Groundhandling Samstag 14.4.18 in Stauf','Schnupper-/Grundkurs + Groundhandling Samstag 14.4.18 in Stauf',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0; height: 38px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center; width: 600px;\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb; width: 520px;\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a></td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 520px; margin: 15px auto;\">\r\n<h3 style=\"text-align: left;\"><span style=\"color: #3491b7;\">Hallo {subtag:name|part:first|ucfirst},</span></h3>\r\n<p style=\"text-align: left;\">morgen am Samstag 14.4.18 fangen wir mit unseren Neuanfängern um&nbsp;<strong>8:30 Uhr in Stauf</strong>&nbsp;an.</p>\r\n<p style=\"text-align: left;\">Bitte seid pünktlich da, damit wir zügig loslegen können.</p>\r\n<p style=\"text-align: left;\">Anfahrts-/Geländebeschreibung Stauf:</p>\r\n<p style=\"text-align: left;\"><a href=\"http://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/57-stauf\">http://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/57-stauf</a></p>\r\n<p style=\"text-align: left;\">Parkplatz: bitte nehmt den Parkplatz für viel Betrieb (am Ende der Ramsener Straße in Eisenberg / Steinborn). Da braucht ihr zu Fuß ca. 5 min bis zum Treffpunkt aber dann seid ihr auch gleich warm ;-)!</p>\r\n<p style=\"text-align: left;\">Am Nachmittag wollen wir ab 14 Uhr zusätzlich noch einen Groundhandlingkurs anbieten. Wir haben 4 Plätze frei, der Kurs dauert 3-4 h und kostet 40,- € p. P. Bitte schreibt uns eine Mail, wenn ihr dabei sein wollt! Wir schreiben euch dann noch bis 21 Uhr zurück, ob ihr dabei seid.<span style=\"font-size: small;\"><strong>&nbsp; &nbsp;</strong></span></p>\r\n<p><strong>Video Infos:</strong></p>\r\n<p style=\"text-align: left;\">...mehr Infos rund ums\'s Gleitschirmfliegen, zu unseren Kursen und Reisen findet ihr auf unserer Website&nbsp;<a href=\"http://www.fs-hirondelle.de/\">www.fs-hirondelle.de</a>&nbsp;sowie in unserem&nbsp;<a href=\"https://www.youtube.com/channel/UCOwo0Wh2zoX_7nyArBdk_IQ\">YouTube-Kanal</a>&nbsp;- schaut einfach mal rein!</p>\r\n<p style=\"text-align: left;\"><span style=\"color: #3491b7;\"><em><strong>Luftige Grüße</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span><br /></span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim &nbsp;| &nbsp;Am Birnbach 6 - 76829 Landau<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span></span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\">Sparkasse SÜW<br />IBAN: DE32 5485 0010 1700 1976 41&nbsp; <br />BIC: SOLADES1SUW<br /><br /></span><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu ermöglichen</strong></span></p>\r\n</td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #ebebeb; height: 40px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Unsubscribe{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2018-04-13 09:40:11.000','2018-04-13 09:31:15.000','2026-09-20 10:04:38.775','NEWSLETTER',702,235,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('678a6d95-3a3e-41f4-b716-a5607395fa3f','Newsletter der Flugschule Hirondelle','Newsletter der Flugschule Hirondelle',NULL,'<div style=\"text-align: center; width: 100%; background-color: #ffffff;\">\r\n<table cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\" style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\">\r\n<tbody>\r\n<tr style=\"line-height: 0px;\">\r\n<td valign=\"bottom\" height=\"38px\" style=\"background-color: #69b4c0;\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td width=\"600\" style=\"text-align: center;\">\r\n<table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin: auto; width: 600px;\">\r\n<tbody>\r\n<tr class=\"acyeditor_delete\">\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n<td width=\"520\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb;\" class=\"acyeditor_text\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"float: left; margin: 0px; margin-right: 20px;\" />\r\n<h3>N e w s l e t t e r</h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n<td style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\" class=\"acyeditor_text\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\"><img src=\"images/Logo-H-web.jpg\" width=\"285\" height=\"92\" /></a><a href=\"https://www.flugschule-hirondelle.de/index.php/ct-menu-item-11\" target=\"_blank\"><img src=\"images/ebcbb8eb50.png\" width=\"200\" height=\"103\" /></a></td>\r\n<td width=\"40\" style=\"background-color: #ebebeb;\">\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n<td width=\"520\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 500px; margin: 15px auto;\" class=\"acyeditor_text\">\r\n<h3>Hallo,</h3>\r\n<p>am Montag 05.01.2015 ist Karsten ab 18:00 Uhr bis ca. 19:00-19:30 Uhr in der Flugschule.</p>\r\n<p>Ab Donnerstag 08.01.2015 sind wir dann in Süd-Afrika und wären am 26.01.2015 wieder erreichbar.</p>\r\n<p>Also wer noch etwas benötigt oder eine Beratung möchte hat am Montag noch die Chance vorbeizukommen. Ansonsten erst wieder nach unserer Süd-Afrika Tour.</p>\r\n<p>Wer noch Interesse an der Süd-Afrika Tour hat kann sich gerne melden bzw. am Montag vorbeikommen.</p>\r\n<p><em><strong>Viele Grüße</strong></em><br /><strong><em>Team Hirondelle</em></strong></p>\r\n<p> </p>\r\n<p><span style=\"font-size: small;\"><strong>                <a href=\"http://shop.flugschule-hirondelle.de/GEBRAUCHT/\" target=\"_blank\" title=\"Zu unserem Gebrauchtmarkt\">HIER GEHTS ZU UNSEREM GEBRAUCHTMARKT</a><br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span> -  </span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -  69469 Weinheim -  Germany<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"> </p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"> <span style=\"font-size: xx-small;\">Flugschule:+49 (</span></span><span style=\"font-family: Arial; font-size: xx-small; font-weight: bold;\"><em><span style=\"font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">0)6341 / 1419165</span></em></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"> - <span style=\"font-size: xx-small;\">Alex Handy:</span></span><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span> - <span style=\"font-size: xx-small;\">Kai Handy:</span></span><span style=\"font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif; font-size: xx-small;\">+49 (0)152 / 01747211</span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><span style=\"color: #e2341d; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"> </span><span style=\"font-size: xx-small;\"><span style=\"color: #e2341d; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Kontonummer: 160 52 16</span>  <span style=\"color: #e2341d; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Bankleitzahl: 670 923 00</span>  <span style=\"color: #e2341d; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Volksbank Weinheim<br />I B A N: DE51670923000001605216      B I C: GENODE61WNM</span></span></span><span style=\"font-weight: bold;\"><br /><br /></span><span style=\"color: #ff0000;\"><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu ermöglichen</strong></span></p>\r\n</td>\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td valign=\"bottom\" height=\"40px\" style=\"background-color: #ebebeb;\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Unsubscribe{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2015-01-03 13:36:10.000','2015-01-03 13:35:11.000','2026-09-20 10:04:35.357','GENERAL',1368,390,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('678f36d7-03e7-4e3d-bacc-f6060a022030','Tandemflüge am Wochenende','Tandemflüge am Wochenende',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0;\" valign=\"bottom\" height=\"38px\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" width=\"600\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb;\" width=\"520\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a><a href=\"https://www.flugschule-hirondelle.de/index.php/ct-menu-item-11\" target=\"_blank\"><img src=\"images/ebcbb8eb50.png\" alt=\"\" width=\"200\" height=\"103\" /></a></td>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 500px; margin: 15px auto;\" width=\"520\">\r\n<h3><span style=\"color: #3491b7;\">Hallo {subtag:name|part:first|ucfirst},</span></h3>\r\n<p>am Wochenende k&ouml;nnen wir wieder ein paar Tandemfl&uuml;ge anbieten. Wenn ihr Lust und Zeit habt, meldet euch bitte bis morgen Abend, 18 Uhr per Email bei uns. Geflogen wird am Samstag und Sonntag in der S&uuml;dpfalz bei Annweiler, bitte gebt Bescheid, an welchem Tag bzw ob ihr vor- oder nachmittags k&ouml;nnt.</p>\r\n<p>Genauere Infos (Ort und Uhrzeit) bekommt ihr nach der Anmeldung per Mail.&nbsp;</p>\r\n<p><span style=\"color: #3491b7;\"><em><strong>Viele Gr&uuml;&szlig;e</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span> -&nbsp; </span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim -&nbsp; Germany<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span></span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\">Sparkasse S&Uuml;W<br />IBAN: DE32 5485 0010 1700 1976 41&nbsp; <br />BIC: SOLADES1SUW<br /><br /></span><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu erm&ouml;glichen</strong></span></p>\r\n</td>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #ebebeb;\" valign=\"bottom\" height=\"40px\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Unsubscribe{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2016-03-17 14:19:02.000','2016-03-17 14:10:14.000','2026-09-20 10:04:36.351','TANDEM',67,31,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('67f8a97d-4c67-497d-92af-503d9307f8f6','Mittwoch Flugschule geöffnet 16-19:30 Uhr','Mittwoch Flugschule geöffnet 16-19:30 Uhr',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0; height: 38px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center; width: 600px;\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb; width: 520px;\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a></td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 520px; margin: 15px auto;\">\r\n<h3 style=\"text-align: left;\"><span style=\"color: #3491b7;\">Hallo {subtag:name|part:first|ucfirst},</span></h3>\r\n<p style=\"text-align: left;\"><strong>Mittwoch 12.8.2020 Flugschule geöffnet, 16-19.30 Uhr !</strong></p>\r\n<p style=\"text-align: left;\">Am Mittwoch sind wir wieder für euch in der Flugschule in Weinheim. Wer was braucht oder mal wieder quatschen will, schaut gerne vorbei. Da die Flugschulräumlichkeiten doch überschaubar sind, und wir natürlich auch die Abstandsregeln einhalten müssen,&nbsp;<strong>meldet euch bitte vorab bei uns per E-Mail mit eurer Wunschuhrzeit an</strong>, damit wir das ein bissel koordinieren können. Wir dürfen euch nämlich leider nur nacheinander reinlassen oder wir hocken uns drausen mit im Hof hin ;-)!</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: left;\"><strong>A-Theorieschulung am kommenden Wochenende -Start Freitag 18 -21 Uhr, Samstag 9-17Uhr:</strong></p>\r\n<p style=\"text-align: left;\">Es sind noch Plätze frei für die A-Theorie am WE. Wir machen wieder eine Webbex Schulung. D.h. ich könnt beqeum von daheim aus mitmachen. Pflichtschulung für alle die jetzt am Wocheende und zukünfitg &nbsp;auf eine Höhenschulung wollen. Bitte meldet euch über folgenden Link an :&nbsp;</p>\r\n<p><a href=\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/12-hoehenflugschulung/856-a-theorie\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/12-hoehenflugschulung/856-a-theorie</a></p>\r\n<p><img src=\"images/1-Bilderfuernewsletter/IMG_0243.JPG\" alt=\"\" width=\"552\" height=\"413\" /></p>\r\n<p style=\"text-align: left;\">...mehr Infos rund ums\'s Gleitschirmfliegen, zu unseren Kursen und Reisen findet ihr auf unserer Website&nbsp;<a href=\"http://www.fs-hirondelle.de/\">www.fs-hirondelle.de</a>&nbsp;sowie in unserem&nbsp;<a href=\"https://www.youtube.com/channel/UCOwo0Wh2zoX_7nyArBdk_IQ\">YouTube-Kanal</a>&nbsp;- schaut einfach mal rein!</p>\r\n<p style=\"text-align: left;\"><span style=\"color: #3491b7;\"><em><strong>Luftige Grüße</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span><br /></span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim &nbsp;| &nbsp;Am Birnbach 6 - 76829 Landau<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span></span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\">Sparkasse SÜW<br />IBAN: DE32 5485 0010 1700 1976 41&nbsp; <br />BIC: SOLADES1SUW</span></span></p>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\"><br /></span><span style=\"font-weight: bold;\"><a href=\"index.php?option=com_content&amp;view=article&amp;id=42:datenschutzerkl%C3%A4rung&amp;catid=2:allgemein\">Datenschutzerklärung</a></span></span></p>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\"><br /></span><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu ermöglichen</strong></span></p>\r\n</td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #ebebeb; height: 40px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Abmelden{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2020-08-06 05:14:52.000','2020-08-06 05:06:25.000','2026-09-20 10:04:40.834','GENERAL',1590,1011,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('681a867c-fb98-4e00-9a61-7f228dbb3759','Newsletter der Flugschule Hirondelle','Newsletter der Flugschule Hirondelle',NULL,'<div style=\"text-align: center; width: 100%; background-color: #ffffff;\">\r\n<table cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\" style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\">\r\n<tbody>\r\n<tr style=\"line-height: 0px;\">\r\n<td valign=\"bottom\" height=\"38px\" style=\"background-color: #69b4c0;\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td width=\"600\" style=\"text-align: center;\">\r\n<table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin: auto; width: 600px;\">\r\n<tbody>\r\n<tr class=\"acyeditor_delete\">\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n<td width=\"520\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb;\" class=\"acyeditor_text\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"float: left; margin: 0px; margin-right: 20px;\" />\r\n<h3>N e w s l e t t e r</h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr>\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n<td style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\" class=\"acyeditor_text\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\"><img src=\"images/Logo-H-web.jpg\" width=\"285\" height=\"92\" /></a><a href=\"https://www.flugschule-hirondelle.de/index.php/ct-menu-item-11\" target=\"_blank\"><img src=\"images/ebcbb8eb50.png\" width=\"200\" height=\"103\" /></a></td>\r\n<td width=\"40\" style=\"background-color: #ebebeb;\">\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n<td width=\"520\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 500px; margin: 15px auto;\" class=\"acyeditor_text\">\r\n<h3>Hallo {subtag:name|part:first|ucfirst},</h3>\r\n<p><strong>Neue Öffnungszeiten Flugschule:</strong></p>\r\n<p>Ab sofort sind wir jede Woche für euch in Weinheim in der Flugschule. Ab nächster Woche Freitag haben wir wöchentlich von 18-20 Uhr geöffnet. Zusätzlich sind wir Mittwochs nach Vorankündigung für euch da.</p>\r\n<p> </p>\r\n<p><strong>Grundkursschulung am Donnerstag, 19.3.15 ab 15 Uhr:</strong><br /><strong> </strong><br />Am Donnerstag schulen wir im Odenwald. Wer Zeit hat und gerne was machen will – einfach per Mail anmelden, der Grundkurs steht ab drei Schülern! Ort wird sehr wahrscheinlich Nonrod sein. Geschult wird ab 15 Uhr.<br />Die Wetteraussichten fürs kommende WE sind bis jetzt zumindest nicht gerade rosig – daher, wenn ihr Zeit habt nutzt den Donnerstag und schaut vorbei ;-)!<br /> <br /> <br /><strong>B-Schein-Theorieseminar am kommenden WE 20. - 22.3.15 mit Prüfung in A- und B-Schein:</strong><br /><strong> </strong><br />Am kommenden Wochenende findet wieder unsere B-Schein-Schulung statt. Wenn sich noch jemand anmelden möchte kann er das gerne tun – wir haben noch einige wenige Plätze frei! Die Schulung findet in unserer Flugschule in Weinheim statt und beginnt am Freitagabend um 18 Uhr. Samstag und Sontag jeweils gegen 9:30 Uhr bis ca. 17 Uhr. Am Sonntagabend findet dann um 18 Uhr die Prüfung vor einem Prüfer des DHV statt. Wer möchte kann zu diesem Zeitpunkt auch gerne noch die A-Scheinprüfung schreiben wenn er bereits die Theorie gehört hat. <br />Die aktuellen Prüfungsfragen findet ihr auf dem Onlineportal des DHV: http://dhv.onlearning.at/index.php <br /> <br /> <br /><strong>Windenschulung Kompaktkurs 26. - 29.3.15:</strong><br /> <br />Kommende Woche bieten wir euch einen Kompaktkurs an der Winde in Haßloch an. Wenn das Wetter mitspielt solltet ihr nach den vier Tagen eure 20 Windenstarts in der Tasche haben. Wer Interesse an dem Kurs hat – gerne melden J!<br /> </p>\r\n<p> <img src=\"images/132_3262_300_300.jpg\" alt=\"\" /></p>\r\n<p> </p>\r\n<p><em><strong>Viele Grüße</strong></em><br /><strong><em>Team Hirondelle</em></strong></p>\r\n<p> </p>\r\n<p><span style=\"font-size: small;\"><strong>               <br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span> -  </span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -  69469 Weinheim -  Germany<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"> </p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"> <span style=\"font-size: xx-small;\">Flugschule:+49 (</span></span><span style=\"font-family: Arial; font-size: xx-small; font-weight: bold;\"><em><span style=\"font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">0)6341 / 1419165</span></em></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"> - <span style=\"font-size: xx-small;\">Alex Handy:</span></span><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span> - <span style=\"font-size: xx-small;\">Kai Handy:</span></span><span style=\"font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif; font-size: xx-small;\">+49 (0)152 / 01747211</span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><span style=\"color: #e2341d; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"> </span><span style=\"font-size: xx-small;\"><span style=\"color: #e2341d; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Kontonummer: 160 52 16</span>  <span style=\"color: #e2341d; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Bankleitzahl: 670 923 00</span>  <span style=\"color: #e2341d; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Volksbank Weinheim<br />I B A N: DE51670923000001605216      B I C: GENODE61WNM</span></span></span><span style=\"font-weight: bold;\"><br /><br /></span><span style=\"color: #ff0000;\"><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu ermöglichen</strong></span></p>\r\n</td>\r\n<td width=\"40\" style=\"background-color: #ebebeb;\"></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td valign=\"bottom\" height=\"40px\" style=\"background-color: #ebebeb;\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Unsubscribe{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2015-03-17 14:14:57.000','2015-03-17 14:14:32.000','2026-09-20 10:04:35.456','GENERAL',1379,404,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('6833a3f9-f314-4a0f-a857-8131ccce1f4c','Freitag 17-20 Uhr Shop geöffnet, Samstag Schnuppertag-/Kurs , Grundkurs fällt leider aus','Freitag 17-20 Uhr Shop geöffnet, Samstag Schnuppertag-/Kurs , Grundkurs fällt leider aus',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0;\" valign=\"bottom\" height=\"38px\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" width=\"600\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb;\" width=\"520\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a><a href=\"https://www.flugschule-hirondelle.de/index.php/ct-menu-item-11\" target=\"_blank\"><img src=\"images/ebcbb8eb50.png\" alt=\"\" width=\"200\" height=\"103\" /></a></td>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 500px; margin: 15px auto;\" width=\"520\">\r\n<h3><span style=\"color: #3491b7;\">Hallo {subtag:name|part:first|ucfirst},</span></h3>\r\n<p><strong>Shop ge&ouml;ffnet Freitag von 17-20 Uhr:</strong></p>\r\n<p><span style=\"font-size: 14pt;\">Morgen am Freitag ist Alex von 17-20 Uhr f&uuml;r euch im Shop in Weinheim.</span></p>\r\n<p><span style=\"font-size: 14pt;\">Falls ihr was braucht oder quatschen wollt kommt gerne vorbei.</span></p>\r\n<p><span style=\"font-size: 10pt;\"><span style=\"font-size: 14pt;\">Wir sind dann erstmal eine Woche bis zum 10.9.16 in Griechenland </span><span style=\"font-size: 14pt; font-family: Wingdings;\">J</span><span style=\"font-size: 14pt;\">. </span></span></p>\r\n<p><span style=\"font-size: 14pt;\">Tester: Wir haben noch ein paar Tester f&uuml;r euch da!</span></p>\r\n<p><span style=\"font-size: 14pt;\">Aktuell auf Lager:</span></p>\r\n<p><span style=\"font-size: 14pt;\">Advance Epsilon 8 25</span></p>\r\n<p><span style=\"font-size: 14pt;\">Advance Epsilon 8 27</span></p>\r\n<p><span style=\"font-size: 14pt;\">Advance Epsilon 8 29 </span></p>\r\n<p><span style=\"font-size: 14pt;\">BGD Adam&nbsp; in S,M,ML,L</span></p>\r\n<p><span style=\"font-size: 14pt;\">BGD Base ML</span></p>\r\n<p><span style=\"font-size: 14pt;\">BGD Dual Tandem</span></p>\r\n<p><span style=\"font-size: 14pt;\">Ozone Buzz Z5 MS</span></p>\r\n<p><span style=\"font-size: 14pt;\">Falls ihr einen von denen Testen wollt gebt uns Bescheid ;-)!</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Schnupperkurs und Grundkurs f&auml;llt am WE aus:</strong></p>\r\n<p><span style=\"font-size: 10pt;\"><span>Rob war schon ganz hei&szlig; auch mal in der Pfalz zu Schulen aber es wir leider nix :-(!&nbsp;</span>Am Wochenende kommt der Wind genau auf Richtung S&uuml;dwest und daf&uuml;r haben wir leider keinen Buckel zur Verf&uuml;gung. &nbsp;F&uuml;r die Neuanf&auml;nger und diejenigen die einen Platz am WE gebucht haben - bitte nochmal an einem anderen Termin eintragen.</span></p>\r\n<p><span style=\"color: #3491b7;\"><em><strong>Viele Gr&uuml;&szlig;e</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span> -&nbsp; </span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim -&nbsp; Germany<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span></span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\">Sparkasse S&Uuml;W<br />IBAN: DE32 5485 0010 1700 1976 41&nbsp; <br />BIC: SOLADES1SUW<br /><br /></span><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu erm&ouml;glichen</strong></span></p>\r\n</td>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #ebebeb;\" valign=\"bottom\" height=\"40px\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Unsubscribe{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2016-09-01 08:08:05.000','2016-09-01 08:06:23.000','2026-09-20 10:04:37.074','GENERAL',1691,493,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('6948d005-038a-4fea-b465-52785ae5573b','Grundkurs-/ Schupperkurs 2. Tag am Sonntag 17.5.18','Grundkurs-/ Schupperkurs 2. Tag am Sonntag 17.5.18',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0; height: 38px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center; width: 600px;\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb; width: 520px;\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a></td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 520px; margin: 15px auto;\">\r\n<h3 style=\"text-align: left;\"><span style=\"color: #3491b7;\">Hallo {subtag:name|part:first|ucfirst},</span></h3>\r\n<p><span style=\"text-align: left;\">morgen am Sonntag 27.5.18 fangen wir um&nbsp;</span><strong style=\"text-align: left;\">8:00 Uhr in Stauf</strong><span style=\"text-align: left;\">&nbsp;an.</span></p>\r\n<p style=\"text-align: left;\">Bitte seid pünktlich da, damit wir zügig loslegen können.</p>\r\n<p style=\"text-align: left;\">Anfahrts-/Geländebeschreibung Stauf:</p>\r\n<p style=\"text-align: left;\"><a href=\"http://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/57-stauf\">http://www.fs-hirondelle.de/nutzungsbedingungen/9-performance/57-stauf</a></p>\r\n<p style=\"text-align: left;\">Parkplatz: bitte nehmt den Parkplatz für viel Betrieb. Da braucht ihr zu Fuß ca. 5 min bis zum Treffpunkt aber dann seid ihr auch gleich warm ;-)!</p>\r\n<p>Achtung: Dieser Newsletter gilt nur für die Leute die &nbsp;für morgen angemeldet sind ;-)!!!</p>\r\n<p style=\"text-align: left;\">&nbsp;</p>\r\n<p style=\"text-align: left;\">...mehr Infos rund ums\'s Gleitschirmfliegen, zu unseren Kursen und Reisen findet ihr auf unserer Website&nbsp;<a href=\"http://www.fs-hirondelle.de/\">www.fs-hirondelle.de</a>&nbsp;sowie in unserem&nbsp;<a href=\"https://www.youtube.com/channel/UCOwo0Wh2zoX_7nyArBdk_IQ\">YouTube-Kanal</a>&nbsp;- schaut einfach mal rein!</p>\r\n<p style=\"text-align: left;\"><span style=\"color: #3491b7;\"><em><strong>Luftige Grüße</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span><br /></span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim &nbsp;| &nbsp;Am Birnbach 6 - 76829 Landau<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">+49 (0)151 / 18836000</span></span></em></span></p>\r\n</address>\r\n<p style=\"margin: 4px 1px 1px; line-height: 100%; text-align: center;\"><span style=\"color: #3491b7;\"><span style=\"font-weight: bold;\">Sparkasse SÜW<br />IBAN: DE32 5485 0010 1700 1976 41&nbsp; <br />BIC: SOLADES1SUW<br /><br /></span><strong>Bitte tragen Sie uns in Ihr Adressbuch ein, <br />um einen einwandfreien Empfang zu ermöglichen</strong></span></p>\r\n</td>\r\n<td style=\"background-color: #ebebeb; width: 40px;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #ebebeb; height: 40px;\" valign=\"bottom\"><img src=\"media/com_acymailing/templates/newsletter-4/bottom.png\" alt=\"---\" width=\"600\" height=\"40\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"info acyeditor_delete acyeditor_text\">Kein Interesse mehr am Newsletter? {unsubscribe}Unsubscribe{/unsubscribe}</div>\r\n</div>','SENT',NULL,'2018-05-26 14:05:45.000','2018-05-26 14:04:09.000','2026-09-20 10:04:39.091','NEWSLETTER',688,215,0,1,'Flugschule Hirondelle','info@fs-hirondelle.de','Flugschule Hirondelle','info@fs-hirondelle.de',NULL,NULL,NULL,NULL,1),('69c588b3-d150-4368-ad56-647ddda6e763','Flugschule heute geöffnet 17:00-19:30 Uhr','Flugschule heute geöffnet 17:00-19:30 Uhr',NULL,'<div style=\"text-align: center; width: 100%; background-color: #fff;\">\r\n<table style=\"text-align: justify; margin: auto; background-color: #ebebeb; border: 1px solid #e7e7e7; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ebebeb\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr style=\"line-height: 0px;\">\r\n<td style=\"background-color: #69b4c0;\" valign=\"bottom\" height=\"38px\"><img src=\"media/com_acymailing/templates/newsletter-4/top.png\" alt=\" - - - \" width=\"600\" height=\"38\" /></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" width=\"600\">\r\n<table border=\"0\" style=\"margin: auto; width: 600px;\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #ebebeb;\" width=\"520\"><img src=\"media/com_acymailing/templates/newsletter-4/message_icon.png\" alt=\"-\" width=\"41\" height=\"41\" style=\"margin: 0px 10px; float: left;\" />\r\n<h3><span style=\"color: #3491b7;\">NEWSLETTER</span></h3>\r\n</td>\r\n</tr>\r\n</tbody>\r\n<tbody class=\"acyeditor_sortable\">\r\n<tr>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"padding: 20px 0px; text-align: left; background-color: #fefefe; width: 520px;\"><a href=\"http://www.flugschule-hirondelle.de/\" target=\"_blank\"><img src=\"images/Logo-H-web.jpg\" alt=\"\" width=\"285\" height=\"92\" /></a><a href=\"https://www.flugschule-hirondelle.de/index.php/ct-menu-item-11\" target=\"_blank\"><img src=\"images/ebcbb8eb50.png\" alt=\"\" width=\"200\" height=\"103\" /></a></td>\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr class=\"acyeditor_delete\">\r\n<td style=\"background-color: #ebebeb;\" width=\"40\">&nbsp;</td>\r\n<td class=\"acyeditor_text\" style=\"background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 500px; margin: 15px auto;\" width=\"520\">\r\n<h3><span style=\"color: #3491b7;\">Hallo {subtag:name|part:first|ucfirst},</span></h3>\r\n<p style=\"text-align: start;\"><span style=\"text-align: center;\">heute ist Alex f&uuml;r euch in der Flugschule in Weinheim.</span></p>\r\n<p style=\"text-align: start;\"><span style=\"text-align: center;\">Falls ihr mal wegen einer eigenen Ausr&uuml;stung oder sonsitgen Sachen mit uns quatschen wollt - schaut gerne rein.</span></p>\r\n<p>Ge&ouml;ffnet ist der Shop von 17-19:30 &nbsp;Uhr</p>\r\n<p><span style=\"color: #3491b7;\"><em><strong>Luftige Gr&uuml;&szlig;e</strong></em></span><br /><span style=\"color: #3491b7;\"><strong><em>Team Hirondelle</em></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: small;\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <br /></strong></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\"><span style=\"font-weight: bold;\"><span style=\"font-size: xx-small;\"><span style=\"font-weight: bold; font-family: Arial,\'Arial Unicode MS\',Helvetica,sans-serif;\">Flugschule Hirondelle</span><br /></span><span style=\"font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\">Untergasse 27 -&nbsp; 69469 Weinheim &nbsp;| &nbsp;Am Birnbach 6 - 76829 Landau<br /></span></span></span></p>\r\n<p style=\"line-height: 100%; margin: 1px; text-align: center;\">&nbsp;</p>\r\n<address style=\"line-height: 100%; margin-top: 1px; margin-bottom: 1px;\">\r\n<p style=\"line-height: 100%; margin-top: 1px; margin-bottom: 10px; text-align: center;\"><span style=\"font-weight: bold; font-size: 14px; font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\"><span style=\"font-size: xx-small;\"><em>Telefon: </em></span></span><span style=\"font-weight: bold; font-size: 14px; font-family: Arial;\"><em><span style=\"font-family: Arial, \'Arial Unicode MS\', Helvetica, sans-serif;\