ktop\":false,\"_meta\":{\"htmlID\":\"u_row_4\",\"htmlClassNames\":\"u_row\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false}},{\"id\":\"rz1vbKcN3h\",\"cells\":[1],\"columns\":[{\"id\":\"PkkSdkq3fS\",\"contents\":[{\"id\":\"IOsZ4btaP-\",\"type\":\"text\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"fontSize\":\"14px\",\"color\":\"#333333\",\"textAlign\":\"left\",\"lineHeight\":\"140%\",\"linkStyle\":{\"inherit\":true,\"linkColor\":\"#0000ee\",\"linkHoverColor\":\"#0000ee\",\"linkUnderline\":true,\"linkHoverUnderline\":true},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_text_2\",\"htmlClassNames\":\"u_content_text\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false,\"text\":\"<p style=\\\"font-size: 16px; font-style: italic;\\\">Bitte in den umliegenden Straßen parken, die Parkplätze im Hof der Flugschule sind den Anwohnern vorbehalten!</p><hr style=\\\"border: none; border-top: 1px solid #ccc; margin: 15px 0;\\\"/><p style=\\\"font-size: 18px; color: #333333; font-weight: bold;\\\">Advance Lightness endlich bei uns eingetroffen.</p><p style=\\\"font-size: 16px; margin-top: 10px;\\\">Wir haben lange auf den Nachfolger des Lightness 3 Liegegurtzeuges von Advance gewartet - nun ist es endlich da.</p>\",\"padding\":\"20px\"},\"hasDeprecatedFontControls\":true},{\"id\":\"2CxyaqQHHv\",\"type\":\"image\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"src\":{\"url\":\"http://localhost:5556/uploads/lightness-advance.png\",\"width\":560,\"height\":\"auto\"},\"textAlign\":\"center\",\"altText\":\"\",\"action\":{\"name\":\"web\",\"values\":{\"href\":\"\",\"target\":\"_blank\"}},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_image_3\",\"htmlClassNames\":\"u_content_image\"},\"selectable\":true,\"draggable\":tr